function mostOnALine(points: number[][]): number {
  const n = points.length;
  if (n <= 2) return n;
  let best = 2;
  for (let i = 0; i < n; i++) {
    for (let j = i + 1; j < n; j++) {
      const [x1, y1] = points[i], [x2, y2] = points[j];
      let count = 0;
      for (const [x, y] of points) {
        // zero cross product means (x, y) is on the line through the pair
        if ((x2 - x1) * (y - y1) === (y2 - y1) * (x - x1)) count++;
      }
      best = Math.max(best, count);
    }
  }
  return best;
}

